def reference_holt_winters(data: List[float], alpha: float, beta: float, gamma: float, season_length: int) -> List[float]:
    """
    Reference implementation of Holt-Winters for validation.
    Returns forecast values.
    """
    n = len(data)
    if n < 2:
        return []

    # Initialize level, trend, and seasonal components
    level = data[0]
    trend = data[1] - data[0] if n > 1 else 0.0
    seasonal = [0.0] * season_length

    forecasts = []
    for i in range(n):
        if i >= season_length:
            # Forecast
            m = i - season_length
            forecast = level + trend + seasonal[m % season_length]
            forecasts.append(forecast)

            # Update
            error = data[i] - forecast
            level = alpha * (data[i] - seasonal[m % season_length]) + (1 - alpha) * (level + trend)
            trend = beta * (level - level) + (1 - beta) * trend
            seasonal[m % season_length] = gamma * (data[i] - level) + (1 - gamma) * seasonal[m % season_length]
        else:
            # Initialize seasonal
            seasonal[i] = data[i] - level

    return forecasts


def reference_cusum(data: List[float], threshold: float = 5.0, drift: float = 0.5) -> List[bool]:
    """
    Reference CUSUM implementation for validation.
    Returns list of drift detection flags.
    """
    if not data:
        return []

    mean = np.mean(data[:10]) if len(data) >= 10 else np.mean(data)
    std = np.std(data[:10]) if len(data) >= 10 else 1.0

    pos_sum = 0.0
    neg_sum = 0.0
    flags = []

    for value in data:
        standardized = (value - mean) / std if std > 0 else 0.0
        pos_sum = max(0.0, pos_sum + standardized - drift)
        neg_sum = max(0.0, neg_sum - standardized - drift)

        flags.append(pos_sum > threshold or neg_sum > threshold)

    return flags


